// hendriawan.min.js COMPLETE VERSION
(function () {

    document.addEventListener("DOMContentLoaded", function () {
  
      if (!window.gsap) {
        console.warn("GSAP not loaded");
        return;
      }
  
      const { gsap } = window;
      const { ScrollTrigger, SplitText, ScrambleTextPlugin } = window;
  
      if (ScrollTrigger) gsap.registerPlugin(ScrollTrigger);
      if (ScrambleTextPlugin) gsap.registerPlugin(ScrambleTextPlugin);
  
      /* =========================================================
         SPLIT MOTION (EXACT VERSION — NO CHANGES)
      ========================================================= */
  
      if (SplitText && ScrollTrigger) {
  
        gsap.registerPlugin(SplitText, ScrollTrigger);
  
        const PRESETS = { /* === PERSIS seperti kode kamu === */ 
          "fade-up": { opacity: 0, y: 40 },
          "fade-down": { opacity: 0, y: -40 },
          "fade-left": { opacity: 0, x: 40 },
          "fade-right": { opacity: 0, x: -40 },
          "slide-up": { y: 80 },
          "slide-down": { y: -80 },
          "slide-left": { x: 80 },
          "slide-right": { x: -80 },
          "zoom-in": { opacity: 0, scale: 0.6 },
          "zoom-out": { opacity: 0, scale: 1.4 },
          "pop": { opacity: 0, scale: 0.3, duration: 0.6, ease: "back.out(2)" },
          "soft-zoom": { opacity: 0, scale: 0.85, duration: 0.9, ease: "power2.out" },
          "rotate-in": { opacity: 0, rotate: 12 },
          "rotate-out": { opacity: 0, rotate: -12 },
          "flip-up": { opacity: 0, rotateX: -90, y: 40, duration: 0.8 },
          "flip-left": { opacity: 0, rotateY: -90, x: -40, duration: 0.8 },
          "flip-right": { opacity: 0, rotateY: 90, x: 40, duration: 0.8 },
          "blur-in": { opacity: 0, blur: 14 },
          "cinematic": { opacity: 0, y: 80, blur: 16, duration: 1.2, ease: "power3.out" },
          "cinematic-strong": { opacity: 0, y: 140, blur: 20, scale: 0.9, duration: 1.4, ease: "power4.out" },
          "hero": { opacity: 0, y: 100, blur: 12, scale: 0.95, duration: 1.6, ease: "power4.out", stagger: 0.03 },
          "smooth": { opacity: 0, y: 24, duration: 0.8, ease: "power4.out" },
          "elastic-up": { opacity: 0, y: 100, duration: 1, ease: "elastic.out(1,0.5)" },
          "bounce-up": { opacity: 0, y: 120, duration: 0.9, ease: "back.out(1.7)" },
          "glitch-in": { opacity: 0, x: -20, blur: 8, duration: 0.4, ease: "steps(2)" },
          "paragraph": { opacity: 0, y: 24, duration: 0.8, stagger: 0.05 },
          "paragraph-blur": { opacity: 0, y: 20, blur: 6, duration: 1, stagger: 0.05 }
        };
  
        function initSplitMotion(root = document) {
  
          root.querySelectorAll("[data-split]").forEach((el) => {
  
            if (el.__SplitMotionInit) return;
            el.__SplitMotionInit = true;
  
            const mode = el.dataset.mode || "words";
            const split = new SplitText(el, { type: mode });
  
            let targets;
            if (mode === "chars") targets = split.chars;
            else if (mode === "lines") targets = split.lines;
            else targets = split.words;
  
            let presetConfig = {};
            for (const name in PRESETS) {
              if (el.hasAttribute(`data-${name}`)) {
                presetConfig = PRESETS[name];
                break;
              }
            }
  
            const fromConfig = {
              opacity: Number(el.dataset.opacity ?? presetConfig.opacity ?? 0),
              x: Number(el.dataset.x ?? presetConfig.x ?? 0),
              y: Number(el.dataset.y ?? presetConfig.y ?? 0),
              z: Number(el.dataset.z ?? presetConfig.z ?? 0),
              scale: Number(el.dataset.scale ?? presetConfig.scale ?? 1),
              rotate: Number(el.dataset.rotate ?? presetConfig.rotate ?? 0),
              rotateX: Number(el.dataset.rotateX ?? presetConfig.rotateX ?? 0),
              rotateY: Number(el.dataset.rotateY ?? presetConfig.rotateY ?? 0),
              filter: `blur(${Number(el.dataset.blur ?? presetConfig.blur ?? 0)}px)`
            };
  
            const toConfig = {
              opacity: 1,
              x: 0,
              y: 0,
              z: 0,
              scale: 1,
              rotate: 0,
              rotateX: 0,
              rotateY: 0,
              filter: "blur(0px)",
              duration: Number(el.dataset.duration ?? presetConfig.duration ?? 0.6),
              delay: Number(el.dataset.delay ?? 0),
              stagger: Number(el.dataset.stagger ?? presetConfig.stagger ?? 0.08),
              ease: el.dataset.ease ?? presetConfig.ease ?? "power2.out"
            };
  
            if (el.dataset.scroll !== "false") {
              toConfig.scrollTrigger = {
                trigger: el,
                start: el.dataset.start || "top 85%",
                end: el.dataset.end || "bottom top",
                toggleActions: "play none none none",
                once: false
              };
            }
  
            gsap.set(targets, fromConfig);
            const tween = gsap.to(targets, toConfig);
  
            const rect = el.getBoundingClientRect();
            if (rect.top < window.innerHeight && rect.bottom > 0) {
              tween.play();
            }
  
          });
        }
  
        initSplitMotion();
        window.SplitMotion = { init: initSplitMotion };
      }
  
      /* =========================================================
         SCRAMBLE TEXT
      ========================================================= */
  
      if (ScrambleTextPlugin) {
        document.querySelectorAll("[data-scramble]").forEach(e => {
  
          gsap.to(e, {
            duration: parseFloat(e.dataset.duration ?? 1),
            delay: parseFloat(e.dataset.delay ?? 0),
            scrambleText: {
              text: e.dataset.text ?? e.textContent,
              chars: e.dataset.chars ?? "@#$*?:"
            },
            scrollTrigger: ScrollTrigger ? {
              trigger: e,
              start: e.dataset.start ?? "top 80%",
              toggleActions: e.dataset.toggle ?? "play none none none"
            } : null
          });
  
        });
      }
  
      /* =========================================================
         MARQUEE
      ========================================================= */
  
      const track = document.getElementById("track");
      if (track) {
        let position = 0;
        let speed = 1.5;
        let targetSpeed = 1.5;
  
        track.addEventListener("mouseenter", () => targetSpeed = 0.15);
        track.addEventListener("mouseleave", () => targetSpeed = 1.5);
  
        function animate() {
          speed += (targetSpeed - speed) * 0.05;
          position -= speed;
          const halfWidth = track.scrollWidth / 2;
          if (Math.abs(position) >= halfWidth) position = 0;
          track.style.transform = `translateX(${position}px)`;
          requestAnimationFrame(animate);
        }
  
        animate();
      }
  
      /* =========================================================
         STAGGER
      ========================================================= */
  
      document.querySelectorAll("[data-stagger]").forEach(parent => {
  
        const children = Array.from(parent.children);
        if (!children.length) return;
  
        gsap.from(children, {
          x: Number(parent.dataset.x ?? 0),
          y: Number(parent.dataset.y ?? 0),
          opacity: parent.dataset.opacity !== undefined ? Number(parent.dataset.opacity) : 0,
          stagger: Number(parent.dataset.stagger ?? 0.1),
          delay: Number(parent.dataset.delay ?? 0),
          scrollTrigger: ScrollTrigger ? {
            trigger: parent,
            start: parent.dataset.start || "top 80%"
          } : null
        });
  
      });
  
    });
  
  })();